// ── Parse and validate incoming reminder data ──────────────
const body = $input.first().json.body || $input.first().json;

const title        = body.title        || 'Rappel';
const description  = body.description  || '';
const datetimeRaw  = body.reminder_datetime;
const userId       = body.user_id      || 'web_user_001';
const timezone     = body.timezone     || 'Africa/Tunis';
const lang         = body.language     || 'fr';

// Validate datetime
if (!datetimeRaw) {
  throw new Error('reminder_datetime is required (ISO 8601 format)');
}

const reminderDate = new Date(datetimeRaw);
if (isNaN(reminderDate.getTime())) {
  throw new Error(`Invalid datetime: ${datetimeRaw}`);
}

const now = new Date();
if (reminderDate <= now) {
  throw new Error('reminder_datetime must be in the future');
}

// Build Google Calendar event times
// Event lasts 15 minutes starting at reminder time
const endDate = new Date(reminderDate.getTime() + 15 * 60 * 1000);

const startISO = reminderDate.toISOString();
const endISO   = endDate.toISOString();

// Build confirmation messages per language
const messages = {
  fr: `✅ Rappel créé : "${title}" le ${reminderDate.toLocaleString('fr-FR', {timeZone: timezone})}`,
  en: `✅ Reminder set: "${title}" on ${reminderDate.toLocaleString('en-US',  {timeZone: timezone})}`,
  ar: `✅ تم ضبط التذكير: "${title}" في ${reminderDate.toLocaleString('ar-TN', {timeZone: timezone})}`
};

return [{
  json: {
    title,
    description,
    reminder_datetime: datetimeRaw,
    start_iso:  startISO,
    end_iso:    endISO,
    user_id:    userId,
    timezone,
    language:   lang,
    confirm_message: messages[lang] || messages['fr'],
    reminder_id: `reminder_${Date.now()}_${userId}`
  }
}];

// ── Build alert payload when reminder fires ────────────────
const data = $('Parse & Validate Datetime').item.json;
const lang = data.language || 'fr';

const alertMessages = {
  fr: `🔔 Rappel : ${data.title}`,
  en: `🔔 Reminder: ${data.title}`,
  ar: `🔔 تذكير: ${data.title}`
};

const ttsTexts = {
  fr: `Rappel ! ${data.title}. Il est l'heure.`,
  en: `Reminder! ${data.title}. It's time.`,
  ar: `تذكير! ${data.title}. حان الوقت.`
};

return [{
  json: {
    ...data,
    alert_message: alertMessages[lang] || alertMessages['fr'],
    tts_text:      ttsTexts[lang]      || ttsTexts['fr'],
    mqtt_state:    'reminder',
    fired_at:      new Date().toISOString()
  }
}];

