const error = $input.first().json;
console.error('[wf_set_reminder] Error:', JSON.stringify(error));

return [{
  json: {
    status: 'error',
    error_message: error.message || 'Unknown error in wf_set_reminder',
    timestamp: new Date().toISOString()
  }
}];
